//! Every probe must give the output of the reference's `XmlWriter` (`p4kr-dataforge/tests/xmlprobe.json`,
//! generated by the maintainers from the reference implementation); a rejected tree must be rejected at the
//! same stage (creation or writing) with the same message. Every mismatch is listed.

use p4kr_xmlwrite::names::{NameFault, NameKind, dotnet_attribute_fault, dotnet_name_fault};
use p4kr_xmlwrite::{Child, Doc, Element, Profile, write};
use serde_json::Value;
use std::borrow::Cow;

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex"))
        .collect()
}

fn text(v: &Value) -> Cow<'static, str> {
    Cow::Owned(v.as_str().expect("text").to_string())
}

/// Attributes of the reference: a name already present keeps its place and takes the new value.
fn attributes(tree: &Value) -> Vec<(Cow<'static, str>, Cow<'static, str>)> {
    let mut attrs: Vec<(Cow<'static, str>, Cow<'static, str>)> = Vec::new();
    for pair in tree["a"].as_array().expect("a") {
        let (key, value) = (text(&pair[0]), text(&pair[1]));
        match attrs.iter_mut().find(|(k, _)| *k == key) {
            Some(slot) => slot.1 = value,
            None => attrs.push((key, value)),
        }
    }
    attrs
}

fn build(tree: &Value) -> Doc<'static> {
    let mut elements = Vec::new();
    let mut todo = vec![(tree, usize::MAX)];
    while let Some((node, parent)) = todo.pop() {
        let id = elements.len();
        elements.push(Element {
            name: text(&node["n"]),
            attrs: attributes(node),
            children: Vec::new(),
        });
        if parent != usize::MAX {
            let slot: &mut Element<'static> = &mut elements[parent];
            slot.children.push(Child::Element(id));
        }
        todo.extend(
            node["c"]
                .as_array()
                .expect("c")
                .iter()
                .rev()
                .map(|c| (c, id)),
        );
    }
    Doc {
        elements,
        root: Some(0),
    }
}

/// First rejection by the reference in tree order: element name, its attributes, then the children.
fn first_fault(doc: &Doc<'_>) -> Option<NameFault> {
    let mut todo = vec![doc.root?];
    while let Some(id) = todo.pop() {
        let el = &doc.elements[id];
        let own = dotnet_name_fault(&el.name, NameKind::Element).or_else(|| {
            el.attrs
                .iter()
                .find_map(|(k, v)| dotnet_attribute_fault(k, v))
        });
        if own.is_some() {
            return own;
        }
        todo.extend(el.children.iter().rev().filter_map(|c| match c {
            Child::Element(kid) => Some(*kid),
            Child::CData(_) => None,
        }));
    }
    None
}

fn expected_fault(row: &Value) -> NameFault {
    let message = row["error"].as_str().expect("error").to_string();
    match row["stage"].as_str() {
        Some("create") => NameFault::Create(message),
        Some("write") => NameFault::Write(message),
        other => panic!("unknown stage {other:?}"),
    }
}

#[test]
fn every_probe_matches_the_reference() {
    let rows: Value =
        serde_json::from_str(include_str!("../../p4kr-dataforge/tests/xmlprobe.json"))
            .expect("xmlprobe.json");
    let rows = rows.as_array().expect("list");
    assert!(rows.len() >= 280, "only {} probes", rows.len());
    let mut failures = Vec::new();
    for row in rows {
        let name = row["name"].as_str().expect("name");
        let doc = build(&row["tree"]);
        if row["error"].is_null() {
            let mut out = Vec::new();
            let got = write(&doc, Profile::DataForge, &mut out);
            let want = unhex(row["xml_hex"].as_str().expect("xml_hex"));
            if got.is_err() || out != want {
                failures.push(format!(
                    "{name}: expected {:?}, got {:?} ({got:?})",
                    String::from_utf8_lossy(&want),
                    String::from_utf8_lossy(&out)
                ));
            }
        } else {
            let (want, got) = (expected_fault(row), first_fault(&doc));
            let mut out = Vec::new();
            let written = write(&doc, Profile::DataForge, &mut out);
            if got.as_ref() != Some(&want) {
                failures.push(format!("{name}: expected {want:?}, got {got:?}"));
            }
            if written != Err(p4kr_xmlwrite::WriteError::Name(want.clone())) {
                failures.push(format!(
                    "{name}: write gives {written:?}, expected {want:?}"
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
